def md_domain_for(suffix: str) -> str:
    parts = suffix.split("_")
    first = parts[0]
    if first in BRAND_FIRST:
        return "MdMisc"
    if first == "phone":
        return "MdCommunication"
    if first == "calendar":
        return "MdTime"
    if first == "bell":
        return "MdAlert"
    if first == "chart":
        return "MdFinance"
    if first == "book":
        return "MdFile"
    if len(parts) >= 2:
        for first_c, second_c, domain_c in MD_COMPOUND_RULES:
            if parts[0] == first_c and parts[1] == second_c:
                return domain_c
    for domain, prefixes in MD_PREFIX_RULES:
        if first in prefixes:
            return domain
    return "MdMisc"

def md_category_for(domain: str, suffix: str) -> str:
    parts = suffix.split("_")
    first = parts[0]
    # domain-specific category routing
    return _md_category_lookup(domain, suffix)

def _md_category_lookup(domain: str, suffix: str) -> str:
    """Generated category lookup."""
    key = (domain, suffix)
    return _MD_CATEGORY_MAP.get(key, pascal_case(suffix.split('_')[0]))

